import type {Ref} from 'react';

/** Selector for elements a Tab key press can land on. */
export const TABBABLE =
  'a[href],button:not([disabled]),input:not([disabled]):not([type=hidden]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';

/** Calls an optional handler with a cancelable event dispatched on `on` (so `currentTarget` is that element) and
 *  reports whether it called `preventDefault()`. */
export const vetoed = (h?: (e: Event) => void, on: EventTarget = document) => {
  const e = new Event('x', {cancelable: true});
  if (h) {
    on.addEventListener('x', h, {once: true});
    on.dispatchEvent(e);
  }
  return e.defaultPrevented;
};

/** Points every ref (callback or object) at the node. */
export const setRefs = <T>(node: T | null, ...refs: Array<Ref<T> | undefined>) => {
  for (const r of refs)
    if (typeof r === 'function') r(node);
    else if (r) (r as {current: T | null}).current = node;
};

/** Roving-list keys shared by Select and the menus. Returns the item to focus next (`undefined` if there is none),
 *  or `null` when the key is not a navigation key. Arrows stop at the ends; letters type ahead, repeating a letter
 *  cycles; a lone Space is not a navigation key. `typed` is per-list scratch state, `{text: '', at: 0}`. */
export function nextItem(
  key: string,
  plain: boolean,
  items: HTMLElement[],
  typed: {text: string; at: number},
): HTMLElement | undefined | null {
  const at = items.indexOf(document.activeElement as HTMLElement);
  if (key === 'ArrowDown') return items[Math.min(at + 1, items.length - 1)];
  if (key === 'ArrowUp') return items[Math.max(at - 1, 0)];
  if (key === 'Home' || key === 'PageUp') return items[0];
  if (key === 'End' || key === 'PageDown') return items[items.length - 1];
  if (key.length !== 1 || !plain) return null;
  const now = Date.now(),
    ch = key.toLowerCase();
  if (ch === ' ' && now - typed.at > 500) return null;
  typed.text = now - typed.at > 500 ? ch : typed.text + ch;
  typed.at = now;
  const from = typed.text.length === 1 ? at + 1 : at;
  return [...items.slice(from), ...items.slice(0, from)].find((o) =>
    o.textContent!.trim().toLowerCase().startsWith(typed.text),
  );
}

/** The index of the next enabled item after `from` in direction `dir`, wrapping round; `from` itself if none is enabled. */
export function nextEnabled(list: ReadonlyArray<{disabled?: boolean | undefined}>, from: number, dir: 1 | -1): number {
  let i = from;
  for (let n = 0; n < list.length; n++) {
    i = (i + dir + list.length) % list.length;
    if (!list[i]!.disabled) break;
  }
  return i;
}

import {
  cloneElement,
  forwardRef,
  isValidElement,
  useCallback,
  version,
  type CSSProperties,
  type HTMLAttributes,
  type ReactElement,
  type ReactNode,
  type Ref,
} from 'react';
import {setRefs} from './overlay';

/** The child's ref: `props.ref` in React 19, `element.ref` before. In React 18 development builds an element that has a ref also has a `props.ref` warning getter that returns undefined, so `'ref' in props` is no test. */
const refOf = (el: ReactElement<{ref?: Ref<unknown> | undefined}>): Ref<unknown> | undefined =>
  Number(version.split('.')[0]) < 19 ? (el as unknown as {ref?: Ref<unknown> | undefined}).ref : el.props.ref;

/** `asChild` without the weight: renders its only child element with the Slot's props merged in. The child's props win,
 *  except `aria-*` and `data-state`, which describe the Slot's own widget and so come from the Slot. Event handlers of
 *  both run (the child's first; the Slot's is skipped when the child called `preventDefault()`); `className` joins;
 *  `style` merges; refs compose. */
type AnyProps = Record<string, unknown> & {style?: CSSProperties | undefined; className?: string | undefined};
export const Slot = forwardRef<HTMLElement, HTMLAttributes<HTMLElement> & {children?: ReactNode | undefined}>(
  function Slot({children, ...slot}, ref) {
    const valid = isValidElement(children);
    const childRef = valid ? refOf(children as ReactElement<{ref?: Ref<unknown> | undefined}>) : undefined;
    // One stable callback while the two refs stay the same, so the child's ref is not detached and re-attached on every render.
    const merged = useCallback(
      (n: HTMLElement | null) => setRefs(n, ref, childRef as Ref<HTMLElement> | undefined),
      [ref, childRef],
    );
    if (!valid) {
      if (children != null)
        console.warn('Monoline: `asChild` needs exactly one React element as its child; nothing was rendered.');
      return null;
    }
    const child = children as ReactElement<AnyProps>,
      own = child.props,
      from = slot as AnyProps;
    const props: AnyProps = {...from, ...own};
    for (const k in own) {
      const a = from[k],
        b = own[k];
      if (/^on[A-Z]/.test(k) && typeof a === 'function' && typeof b === 'function') {
        props[k] = (e: {defaultPrevented?: boolean | undefined}, ...x: unknown[]) => {
          (b as (...a: unknown[]) => void)(e, ...x);
          if (!e?.defaultPrevented) (a as (...a: unknown[]) => void)(e, ...x);
        };
      }
    }
    for (const k in from) if (k === 'data-state' || k.startsWith('aria-')) props[k] = from[k];
    if (from.style || own.style) props.style = {...from.style, ...own.style};
    if (from.className || own.className) props.className = [from.className, own.className].filter(Boolean).join(' ');
    props.ref = merged;
    return cloneElement(child, props);
  },
);
